(()=>{"use strict";const e=document.querySelector("form"),r=document.querySelector("input"),t=document.querySelector("#error-message"),n=document.querySelector("#weather-message");e?.addEventListener("submit",o=>{o.preventDefault();const s=r?.value;s&&fetch(`/weather?address=${s}`).then(e=>{if(!e.ok)throw new Error("Network response was not ok");return e.json()}).then(e=>{e.error?(t&&(t.innerHTML=e.error),n&&(n.innerHTML="")):(n&&(n.innerHTML=`Forecast for: ${e.address}: ${e.forecast}`),t&&(t.innerHTML=""))}).catch(e=>{t&&(t.innerHTML=e),n&&(n.innerHTML="")}),e.reset()})})();